-- Read-only metadata receipt; never exports URLs, cache content or account IDs.
select jsonb_build_object(
 'functions',(select jsonb_agg(jsonb_build_object('name',p.proname,'md5',md5(pg_get_functiondef(p.oid)),'acl',p.proacl::text,'securityDefiner',p.prosecdef) order by p.proname) from pg_proc p where p.oid in('public.upsert_link_preview(text,text,text,text,text)'::regprocedure,'public.claim_link_preview_fetch(uuid)'::regprocedure,'public.claim_link_preview_image(uuid)'::regprocedure,'public.store_verified_link_preview(text,text,text,text,text,text)'::regprocedure)),
 'cache',(select jsonb_build_object('acl',c.relacl::text,'rls',c.relrowsecurity,'columns',(select jsonb_agg(a.attname order by a.attnum) from pg_attribute a where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),'verifiedRows',(select count(*) from public.link_previews where verified_at is not null),'unverifiedMetadataRows',(select count(*) from public.link_previews where verified_at is null and(title is not null or description is not null or image_url is not null or image_origin_url is not null)),'policies',(select jsonb_agg(jsonb_build_object('name',polname,'cmd',polcmd,'using',pg_get_expr(polqual,polrelid),'check',pg_get_expr(polwithcheck,polrelid))) from pg_policy p where p.polrelid=c.oid)) from pg_class c where c.oid='public.link_previews'::regclass),
 'budgets',(select jsonb_agg(jsonb_build_object('name',c.relname,'schemaAcl',n.nspacl::text,'tableAcl',c.relacl::text,'rls',c.relrowsecurity,'policyCount',(select count(*) from pg_policy p where p.polrelid=c.oid)) order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='link_preview_service' and c.relkind='r')
) postflight;
